import { PmNodeType } from './../../_shared/pm-node-types.js';
import { findParentNodeClosestToPos } from './../../tiptap/core/index.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';
import type { EditorState } from './../../tiptap/pm/state.js';
import { NodeSelection, Plugin, PluginKey } from './../../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';

// A live color drag fires many change events. To keep the undo history clean
// (one entry per color change, not one per dragged shade), the picker previews
// the color WITHOUT mutating the document and commits a single transaction on
// release. This plugin carries the previewed color as a node decoration on the
// affected node — the target Cell(s), or the Smart Block itself for the
// SOLID_JOINED_BOXES border (a block-level attribute). `SmartBlockCell` /
// `SmartBlock` read it (decoration spec) and render the preview through their
// normal path. The state is set via a meta-only transaction (no steps) so it
// never enters prosemirror-history — mirrors the table plugin's
// `setTableCellStylePreview`.
export type SmartBlockColorPreviewValue = {
  attr: 'accentColor' | 'backgroundColor' | 'shapeColor' | 'borderColor';
  color: string | undefined;
};

export type SmartBlockColorPreview = SmartBlockColorPreviewValue | null;

export const SMART_BLOCK_COLOR_PREVIEW_KEY = new PluginKey<SmartBlockColorPreview>(
  'smartBlockColorPreview'
);

type NodeWithPos = { node: PmNode; pos: number };

const resolveTargetBlock = (state: EditorState): NodeWithPos | null => {
  const { selection } = state;
  if (selection instanceof NodeSelection && selection.node.type.name === PmNodeType.SMART_BLOCK) {
    return { node: selection.node, pos: selection.from };
  }
  const block = findParentNodeClosestToPos(
    state.doc.resolve(selection.from),
    node => node.type.name === PmNodeType.SMART_BLOCK
  );
  return block ? { node: block.node, pos: block.pos } : null;
};

// Resolve which cells the preview applies to from the live selection — the same
// "selected cell vs. whole block" split the color commit commands use.
const resolveTargetCells = (state: EditorState): NodeWithPos[] => {
  const { selection } = state;

  if (
    selection instanceof NodeSelection &&
    selection.node.type.name === PmNodeType.SMART_BLOCK_CELL
  ) {
    return [{ node: selection.node, pos: selection.from }];
  }

  const block = resolveTargetBlock(state);
  if (!block) {
    return [];
  }

  const cells: NodeWithPos[] = [];
  block.node.forEach((child, offset) => {
    if (child.type.name === PmNodeType.SMART_BLOCK_CELL) {
      cells.push({ node: child, pos: block.pos + 1 + offset });
    }
  });
  return cells;
};

export const createSmartBlockColorPreviewPlugin = () =>
  new Plugin<SmartBlockColorPreview>({
    key: SMART_BLOCK_COLOR_PREVIEW_KEY,
    state: {
      init: () => null,
      apply(tr, value) {
        const meta = tr.getMeta(SMART_BLOCK_COLOR_PREVIEW_KEY);
        return meta === undefined ? value : (meta as SmartBlockColorPreview);
      },
    },
    props: {
      decorations(state) {
        const preview = SMART_BLOCK_COLOR_PREVIEW_KEY.getState(state);
        if (!preview) {
          return null;
        }

        // SOLID_JOINED_BOXES keeps its border on the block node, not the cells, so
        // its border preview decorates the block itself; all other colors fall to cells.
        if (preview.attr === 'borderColor') {
          const block = resolveTargetBlock(state);
          if (block?.node.attrs.type === 'SOLID_JOINED_BOXES') {
            return DecorationSet.create(state.doc, [
              Decoration.node(
                block.pos,
                block.pos + block.node.nodeSize,
                {},
                { sbPreviewAttr: preview.attr, sbPreviewColor: preview.color }
              ),
            ]);
          }
        }

        const cells = resolveTargetCells(state);
        if (cells.length === 0) {
          return null;
        }
        return DecorationSet.create(
          state.doc,
          cells.map(({ node, pos }) =>
            // Data rides on the decoration spec (4th arg) so nothing is written
            // to the cell DOM; SmartBlockCell reads it from its `decorations` prop.
            Decoration.node(
              pos,
              pos + node.nodeSize,
              {},
              { sbPreviewAttr: preview.attr, sbPreviewColor: preview.color }
            )
          )
        );
      },
    },
  });
