import { generateId } from './../../ricos-content/index.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import type { EditorState } from './../../tiptap/pm/state.js';
import { Plugin, PluginKey, TextSelection } from './../../tiptap/pm/state.js';
import { findWrapping } from './../../tiptap/pm/transform.js';

import { SMART_BLOCK_DEFAULTS } from '../consts.js';

export const createSmartBlockCellNormalizingPlugin = () => {
  return new Plugin({
    key: new PluginKey('normalize-smart-block-cell'),
    appendTransaction: (_, oldState: EditorState, newState: EditorState) => {
      if (newState.doc.eq(oldState.doc) && newState.selection.eq(oldState.selection)) {
        return;
      }

      const tr = newState.tr;

      // Remove empty smart blocks (layout with single empty cell)
      // Collect positions first, then delete in reverse to avoid stale positions
      const toDelete: { pos: number; size: number }[] = [];
      tr.doc.forEach((node, pos) => {
        if (
          node.type.name === PmNodeType.SMART_BLOCK &&
          node.childCount === 1 &&
          node.firstChild?.childCount === 0
        ) {
          toDelete.push({ pos, size: node.nodeSize });
        }
      });
      for (let i = toDelete.length - 1; i >= 0; i--) {
        const mapped = tr.mapping.map(toDelete[i].pos);
        tr.deleteRange(mapped, mapped + toDelete[i].size);
      }

      // Collect orphaned cells first (iterating original doc to get stable positions),
      // then process in reverse so later positions stay valid as we wrap earlier ones.
      const orphanedCellPositions: number[] = [];
      newState.doc.descendants((node, pos, parent) => {
        if (
          node.type.name === PmNodeType.SMART_BLOCK_CELL &&
          parent?.type.name !== PmNodeType.SMART_BLOCK
        ) {
          orphanedCellPositions.push(pos);
        }
      });
      for (let i = orphanedCellPositions.length - 1; i >= 0; i--) {
        const mappedPos = tr.mapping.map(orphanedCellPositions[i]);
        const cellNode = tr.doc.nodeAt(mappedPos);
        if (!cellNode) {
          continue;
        }
        const $from = tr.doc.resolve(mappedPos);
        const $to = tr.doc.resolve(mappedPos + cellNode.nodeSize);
        const nodeRange = $from.blockRange($to);
        // Adopt the orphaned cell's own variant for the wrapping block so a
        // copy-pasted cell keeps its design (e.g. SIDE_LINE_TEXT) instead of
        // collapsing to the default SOLID_BOXES.
        const wrapping =
          nodeRange &&
          findWrapping(nodeRange, newState.schema.nodes[PmNodeType.SMART_BLOCK], {
            id: generateId(),
            type: cellNode.attrs.type ?? SMART_BLOCK_DEFAULTS.type,
          });

        if (!wrapping) {
          // Remove cell that can't be wrapped to prevent document corruption
          tr.delete(mappedPos, mappedPos + cellNode.nodeSize);
          continue;
        }

        tr.wrap(nodeRange, wrapping);
      }

      tr.doc.descendants((node, pos, parent) => {
        // All smart block cells must have the same type as their parent block
        if (
          node.type.name === PmNodeType.SMART_BLOCK_CELL &&
          parent?.type.name === PmNodeType.SMART_BLOCK &&
          node.attrs.type !== parent.attrs.type &&
          parent.attrs.type
        ) {
          tr.setNodeAttribute(pos, 'type', parent.attrs.type);
        }

        // All empty smart block cells must have an empty paragraph
        if (
          node.type.name === PmNodeType.SMART_BLOCK_CELL &&
          parent?.type.name === PmNodeType.SMART_BLOCK &&
          node.childCount === 0
        ) {
          const paragraphNode = newState.schema.nodes.PARAGRAPH.create({
            id: generateId(),
          });
          const insertPos = pos + 1;
          tr.insert(insertPos, paragraphNode);
          const textPos = insertPos + 1;
          tr.setSelection(TextSelection.create(tr.doc, textPos));
        }
      });

      return tr;
    },
  });
};
