import classNames from 'classnames';
import React, {
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { SmartBlockData_Type } from './../../ricos-schema/next-schema/index.js';
import { type PluginProps } from './../../ricos-types/index.js';
import type { PmSmartBlockCellNode } from './../../_shared/pm-node-types.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';

import { ShapeOverlay } from '../components/shape-overlay.js';
import { SmartBlockCellView } from '../components/smart-block-cell-view.js';
import { SMART_BLOCK_DEFAULTS } from '../consts.js';
import { DATA_HOOKS } from '../data-hooks.js';
import {
  getCellPositionDataAttrs,
  getColumnsPerRow,
  getResponsiveColumnsPerRow,
} from '../utils/cell-position.js';
import { pmCellToViewModel } from '../utils/cell-view-model.js';
import { getJoinedBoxesResponsiveCornerFlags } from '../utils/get-joined-boxes-responsive-corner-flags.js';
import { resolveThemeSmartBlock } from '../utils/resolve-theme-smart-block.js';
import { ShapeOverlayContext, SmartBlockCellEditorContext } from '../utils/smart-block-context.js';
import { openCellShapePicker } from './open-cell-shape-picker.js';
import type { SmartBlockColorPreviewValue } from './smart-block-color-preview-plugin.js';
import styles from './smart-block-editor-scss.js';

export const SmartBlockCell: React.FC<PluginProps> = ({
  node,
  NodeViewContent,
  editor,
  getPos,
  selected,
  updateAttributes,
  decorations,
}) => {
  const { theme } = useContext(RicosContext);
  const themeSmartBlock = useMemo(() => resolveThemeSmartBlock(theme), [theme]);
  // Force re-render when editor state changes (e.g., when cells are added/removed)
  const [, forceUpdate] = useState(0);
  const cellRef = useRef<HTMLDivElement>(null);
  const [hasFocusWithin, setHasFocusWithin] = useState(false);

  const attrs = node.attrs as PmSmartBlockCellNode['attrs'];

  useEffect(() => {
    if (!editor) {
      return;
    }

    const handleUpdate = () => {
      forceUpdate(n => n + 1);
    };

    editor.on('update', handleUpdate);
    return () => {
      editor.off('update', handleUpdate);
    };
  }, [editor]);

  // Eagerly sync data-last-row attrs to the DOM on every editor update, before paint.
  // This prevents a one-frame stale-grid-column state when a sibling cell is added,
  // which would otherwise make autoUpdate(animationFrame: true) read a wrong rect
  // and cause the floating toolbar to jitter by ~3-5px.
  // The forceUpdate above still drives the full React re-render; this effect only
  // patches the CSS-critical attrs synchronously so the intermediate state is gone.
  useLayoutEffect(() => {
    if (!editor) {
      return;
    }

    const syncPositionAttrs = () => {
      const cell = cellRef.current;
      if (!cell || typeof getPos !== 'function') {
        return;
      }
      const pos = getPos();
      if (typeof pos !== 'number') {
        return;
      }

      // Guard: verify pos still refers to this cell (not the newly inserted one
      // when addSmartBlockCellBefore shifted our position in the document).
      const cellId = cell.getAttribute('data-smart-block-cell');
      try {
        const resolvedNode = editor.state.doc.nodeAt(pos);
        if (!resolvedNode || resolvedNode.attrs.id !== cellId) {
          return;
        }

        const $pos = editor.state.doc.resolve(pos);
        const parent = $pos.parent;
        const total = parent.childCount;
        const index = $pos.index($pos.depth);
        const colSize = (parent.attrs.columnSize as string) ?? SMART_BLOCK_DEFAULTS.columnSize;
        const posAttrs = getCellPositionDataAttrs(index, total, colSize);

        for (const [key, val] of Object.entries(posAttrs)) {
          if (val === undefined) {
            cell.removeAttribute(key);
          } else {
            cell.setAttribute(key, val === true ? '' : String(val));
          }
        }
      } catch {
        // Ignore transient resolve errors (e.g., during undo past cell deletion)
      }
    };

    editor.on('update', syncPositionAttrs);
    return () => {
      editor.off('update', syncPositionAttrs);
    };
  }, [editor, getPos]);

  // Track whether the editor selection is inside this cell (but not node-selected)
  useEffect(() => {
    if (!editor || typeof getPos !== 'function') {
      return;
    }

    const checkSelection = () => {
      const pos = getPos();
      if (typeof pos !== 'number') {
        setHasFocusWithin(false);
        return;
      }
      const { from, to } = editor.state.selection;
      const nodeEnd = pos + node.nodeSize;
      const isInside = from >= pos && to <= nodeEnd;
      setHasFocusWithin(isInside && !selected);
    };

    editor.on('selectionUpdate', checkSelection);
    checkSelection();

    return () => {
      editor.off('selectionUpdate', checkSelection);
    };
  }, [editor, getPos, node.nodeSize, selected]);

  // Walk PM's $pos to derive everything the view-model needs about this
  // cell's position in its block. Re-runs each render (forceUpdate keeps it
  // fresh) so the cell stays in sync with sibling additions / removals.
  const parentContext = (() => {
    const defaults = {
      cellIndex: 0,
      totalCells: 1,
      columnSize: SMART_BLOCK_DEFAULTS.columnSize as string,
      orientation: 'HORIZONTAL' as 'HORIZONTAL' | 'VERTICAL',
      isShapesMode: false,
      type: SMART_BLOCK_DEFAULTS.type as SmartBlockData_Type,
    };
    if (!editor || typeof getPos !== 'function') {
      return defaults;
    }
    const pos = getPos();
    if (typeof pos !== 'number') {
      return defaults;
    }
    try {
      const $pos = editor.state.doc.resolve(pos);
      const parent = $pos.parent;
      const total = parent.childCount;
      const index = $pos.index($pos.depth);
      const type = (parent.attrs.type as SmartBlockData_Type) ?? defaults.type;
      const columnSize = (parent.attrs.columnSize as string) ?? SMART_BLOCK_DEFAULTS.columnSize;
      const orientation = (parent.attrs.orientation ?? 'HORIZONTAL') as 'HORIZONTAL' | 'VERTICAL';
      let hasAnyShape = false;
      parent.forEach(child => {
        if (child.type.name === PmNodeType.SMART_BLOCK_CELL && child.attrs.shape) {
          hasAnyShape = true;
        }
      });
      return {
        cellIndex: index,
        totalCells: total,
        type,
        columnSize,
        orientation,
        isShapesMode: hasAnyShape,
      };
    } catch {
      return defaults;
    }
  })();

  const {
    cellIndex,
    totalCells,
    type: blockType,
    columnSize: blockColumnSize,
    orientation: blockOrientation,
    isShapesMode,
  } = parentContext;

  // Live color-drag preview arrives as a node decoration (carried on its spec by
  // the color-preview plugin) — no document mutation. Override the matching
  // view-model color so the cell renders the preview through its normal path
  // (CSS vars for accent/bg, ShapeViewRenderer for shape).
  const colorPreview = useMemo(() => {
    const spec = decorations?.find(deco => deco.spec?.sbPreviewAttr)?.spec;
    if (!spec?.sbPreviewAttr) {
      return null;
    }
    return {
      attr: spec.sbPreviewAttr as SmartBlockColorPreviewValue['attr'],
      color: spec.sbPreviewColor as SmartBlockColorPreviewValue['color'],
    };
  }, [decorations]);

  const viewModel = useMemo(() => {
    const base = pmCellToViewModel(node, {
      type: blockType,
      cellIndex,
      totalCells,
      columnSize: blockColumnSize,
      orientation: blockOrientation,
      isShapesMode,
    });
    if (!colorPreview) {
      return base;
    }
    if (colorPreview.attr === 'shapeColor') {
      return { ...base, shapeColor: colorPreview.color };
    }
    return {
      ...base,
      cellColors: { ...base.cellColors, [colorPreview.attr]: colorPreview.color },
    };
  }, [
    node,
    blockType,
    cellIndex,
    totalCells,
    blockColumnSize,
    blockOrientation,
    isShapesMode,
    colorPreview,
  ]);

  // SOLID_JOINED_BOXES-only: per-cell corner rounding for the editor where
  // `.editorWrapper [data-type="SOLID_JOINED_BOXES"]` overrides
  // `overflow: hidden` → `overflow: visible` (so drag handles + add-cell
  // button aren't clipped). With the wrapper clip gone, corner cells round
  // themselves via the `data-corner-*` attrs spread below. See
  // `tiptap/smart-block-editor.scss:9-44`. Viewer doesn't need this.
  const joinedCornerFlags = useMemo(() => {
    if (blockType !== 'SOLID_JOINED_BOXES') {
      return undefined;
    }
    return getJoinedBoxesResponsiveCornerFlags({
      cellIndex,
      totalCells,
      columnsPerRow: getColumnsPerRow(blockColumnSize),
      responsiveColumnsPerRow: getResponsiveColumnsPerRow(blockColumnSize),
    });
  }, [blockType, cellIndex, totalCells, blockColumnSize]);

  const handleAddShapeClick = useCallback(
    (event: React.MouseEvent<HTMLButtonElement>) =>
      openCellShapePicker(editor, attrs.id, event.currentTarget),
    [editor, attrs.id]
  );

  return (
    <SmartBlockCellEditorContext.Provider
      value={useMemo(
        () => ({
          onLabelChange: label => updateAttributes({ label }),
          onShapeClick: handleAddShapeClick,
        }),
        [updateAttributes, handleAddShapeClick]
      )}
    >
      {/* The overlay is injected rather than imported by SmartBlockCellView:
          it renders a WDS ToggleButton, and the cell view also ships to the
          viewer. See ShapeOverlayContext. */}
      <ShapeOverlayContext.Provider value={ShapeOverlay}>
        <SmartBlockCellView
          viewModel={viewModel}
          themeSmartBlock={themeSmartBlock}
          outerRef={cellRef}
          outerClassName={classNames(styles.editorCell, {
            [styles.cellSelected]: selected,
            [styles.cellFocusWithin]: hasFocusWithin,
          })}
          extraAttrs={joinedCornerFlags}
          contentSlot={contentProps => <NodeViewContent {...contentProps} />}
          overlayChildren={
            <div contentEditable={false} className={styles.cellHandleWrapper}>
              <div
                role="button"
                tabIndex={0}
                draggable
                className={styles.cellDragHandle}
                data-drag-handle=""
                data-smart-block-cell-handle=""
                data-hook={DATA_HOOKS.SMART_BLOCK_CELL_HANDLE}
                onClick={() => {
                  const cellId = cellRef.current?.getAttribute('data-smart-block-cell');
                  if (cellId && editor) {
                    editor.chain().selectSmartBlockCell(cellId).run();
                  }
                }}
                onKeyDown={event => {
                  if (event.key !== 'Enter' && event.key !== ' ') {
                    return;
                  }
                  event.preventDefault();
                  const cellId = cellRef.current?.getAttribute('data-smart-block-cell');
                  if (cellId && editor) {
                    editor.chain().selectSmartBlockCell(cellId).run();
                  }
                }}
              >
                <ThreeDotsIcon />
              </div>
            </div>
          }
        />
      </ShapeOverlayContext.Provider>
    </SmartBlockCellEditorContext.Provider>
  );
};

// Three-dot horizontal icon for drag handle
const ThreeDotsIcon: React.FC = () => (
  <svg viewBox="0 0 18 18" fill="currentColor" width="18" height="18">
    <path d="M4,8 L6,8 L6,10 L4,10 L4,8 Z M8,8 L10,8 L10,10 L8,10 L8,8 Z M12,8 L14,8 L14,10 L12,10 L12,8 Z" />
  </svg>
);
