import { PmNodeType } from './../../_shared/pm-node-types.js';
import type { Editor } from './../../tiptap/react/index.js';

import { SmartBlockShapePickerModal } from '../components/smart-block-shape-picker-modal.js';
import { DATA_HOOKS } from '../data-hooks.js';

// Opens the per-cell shape picker plugin panel anchored to `referenceElement`.
// Shared by three editor entry points that all open the same panel for a given
// cellId: the cell-level accessory click (smart-block-cell), the CIRCLE segment
// indicators, and the STAIRCASE mobile-stack bars (smart-block). The latter two
// live outside the per-cell context, so they pass the cellId explicitly.
export const openCellShapePicker = (
  editor: Editor | null,
  cellId: string,
  referenceElement: HTMLElement
): void => {
  if (!editor) {
    return;
  }
  const smartBlockExt = editor.extensionManager.extensions.find(
    ext => ext.name === PmNodeType.SMART_BLOCK
  );
  const services = smartBlockExt?.options?.services;
  if (!services) {
    return;
  }
  services.modals.togglePluginPanel({
    id: DATA_HOOKS.CELL_SHAPE_PICKER,
    Component: SmartBlockShapePickerModal,
    componentProps: { cellId },
    isMobile: services.context.isMobile,
    positioning: {
      referenceElement,
      placement: 'bottom',
    },
  });
};
